macro_rules! Generalization {
    () => {
        # [doc = " Result from a generalization operation. This includes"] # [doc = " not only the generalized type, but also a bool flag"] # [doc = " indicating whether further WF checks are needed."] # [derive (Debug)] struct Generalization < T > { # [doc = " When generalizing `<?0 as Trait>::Assoc` or"] # [doc = " `<T as Bar<<?0 as Foo>::Assoc>>::Assoc`"] # [doc = " for `?0` generalization returns an inference"] # [doc = " variable."] # [doc = ""] # [doc = " This has to be handled wotj care as it can"] # [doc = " otherwise very easily result in infinite"] # [doc = " recursion."] pub value_may_be_infer : T , # [doc = " In general, we do not check whether all types which occur during"] # [doc = " type checking are well-formed. We only check wf of user-provided types"] # [doc = " and when actually using a type, e.g. for method calls."] # [doc = ""] # [doc = " This means that when subtyping, we may end up with unconstrained"] # [doc = " inference variables if a generalized type has bivariant parameters."] # [doc = " A parameter may only be bivariant if it is constrained by a projection"] # [doc = " bound in a where-clause. As an example, imagine a type:"] # [doc = ""] # [doc = "     struct Foo<A, B> where A: Iterator<Item = B> {"] # [doc = "         data: A"] # [doc = "     }"] # [doc = ""] # [doc = " here, `A` will be covariant, but `B` is unconstrained."] # [doc = ""] # [doc = " However, whatever it is, for `Foo` to be WF, it must be equal to `A::Item`."] # [doc = " If we have an input `Foo<?A, ?B>`, then after generalization we will wind"] # [doc = " up with a type like `Foo<?C, ?D>`. When we enforce `Foo<?A, ?B> <: Foo<?C, ?D>`,"] # [doc = " we will wind up with the requirement that `?A <: ?C`, but no particular"] # [doc = " relationship between `?B` and `?D` (after all, these types may be completely"] # [doc = " different). If we do nothing else, this may mean that `?D` goes unconstrained"] # [doc = " (as in #41677). To avoid this we emit a `WellFormed` obligation in these cases."] pub has_unconstrained_ty_var : bool , }
    };
}

Generalization!();